const metrics = $json;
const inspectionRate = metrics.stormLeads ? Math.round((metrics.inspectionsBooked / metrics.stormLeads) * 100) : 0;
const digest = `Roofing Storm Pipeline Digest
Period: ${metrics.period}
Storm leads: ${metrics.stormLeads}
Inspections booked: ${metrics.inspectionsBooked} (${inspectionRate}%)
Missed calls: ${metrics.missedCalls}
Active claims: ${metrics.claimsActive}
Missing documents: ${metrics.missingDocuments}
Open estimates: ${metrics.openEstimates}
Unsigned contracts: ${metrics.unsignedContracts}
Review opportunities: ${metrics.reviewOpportunities}
Workflow failures: ${metrics.workflowFailures}`;
return [{ json: { ...metrics, inspectionRate, digest } }];
